namespace Util {

// Recovered from the branch target and the two symbols: the call is
// T::Fix(long) on the pointer, tail-called, so the body is one word.
template <class T>
void RTTID_Fix(void* p, long l) {
    ((T*)p)->Fix(l);
}

}  // namespace Util

